import { getSetting } from "../settings/store.js";
import { CONNECT_APPS_FLAG, registerFeatureFlags, } from "./registry.js";
import { mutateFeatureFlagRules } from "./store.js";
/** A tiny startup plugin for app-local, explicit feature-flag registration. */
export function createFeatureFlagsPlugin(options) {
    return async () => {
        registerFeatureFlags([CONNECT_APPS_FLAG, ...options.flags]);
        if (!options.legacyBooleanSetting)
            return;
        const legacy = await getSetting(options.legacyBooleanSetting.settingKey);
        if (!legacy)
            return;
        await Promise.all(options.legacyBooleanSetting.flagKeys.map(async (key) => {
            if (legacy[key] !== true)
                return;
            await mutateFeatureFlagRules(key, {}, (current) => {
                if (current.updatedAt !== null)
                    return current;
                return {
                    ...current,
                    mode: "on",
                    updatedAt: Date.now(),
                    updatedBy: "legacy-settings-migration",
                };
            });
        }));
    };
}
